create table if not exists public.ai_council_runs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, business_id uuid, task_type text not null, question text not null, provider_results jsonb not null default '[]'::jsonb, contradictions jsonb not null default '[]'::jsonb, consensus jsonb not null default '{}'::jsonb, final_answer text, confidence numeric(5,4) not null default 0 check (confidence >= 0 and confidence <= 1), evidence_ids uuid[] not null default '{}'::uuid[], status text not null default 'pending' check (status in ('pending','running','completed','partial','failed')), created_at timestamptz not null default now(), completed_at timestamptz); create index if not exists idx_council_workspace_created on public.ai_council_runs(workspace_id, created_at desc); alter table public.ai_council_runs enable row level security; create policy "members_read_ai_council_runs" on public.ai_council_runs for select to authenticated using (public.is_workspace_member(auth.uid(), workspace_id));;
